class LessonStage(TypedDict):
    """A stage's own data (content/stages/S1/stage.yaml), the record whose ID is a stage: what the
    page needs beyond the spine's tables, which the build joins to the registry (the lessons, the
    lab, the anchors and the drawers the spine lists). A production-twin card and a dated reading
    card are cards. extra holds what a later task needs before a field names it. The file starts
    with schema: statespace/lesson@1, which is how GATE-schema finds it.
    """
    schema: LessonSchemaTag
    id: LessonStageId
    draft: bool
    # A short paragraph shown at the head of the stage page.
    summary: NotRequired[LessonMd]
    # The stage's new tool, in learner words.
    newTool: NotRequired[LessonLine]
    # The roadmap's time for the stage, as the roadmap states it.
    roadmapTime: NotRequired[LessonLine]
    # The seams the stage plants.
    seams: NotRequired[list[SeamId]]
    # The audit anchors the stage serves.
    anchors: NotRequired[list[LessonAnchorId]]
    # The drawers the stage page lists.
    drawers: NotRequired[list[LessonDrawerId]]
    # The stage's production-twin, dated-incident and reading cards.
    cards: NotRequired[list[LessonCardBlock]]
    # A short description of the stage's Defence for the stage page.
    defence: NotRequired[LessonMd]
    extra: NotRequired[dict[str, Any]]


